def transform(grid):
    h, w = len(grid), len(grid[0])
    markers = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 5]
    if len(markers) < 2:
        return grid

    def nearby(p):
        r, c = p
        return sum(
            grid[i][j] != 0
            for i in range(max(0, r-3), min(h, r+4))
            for j in range(max(0, c-3), min(w, c+4))
            if (i, j) != p
        )

    source = max(markers, key=nearby)
    target = next(p for p in markers if p != source)
    dr, dc = target[0] - source[0], target[1] - source[1]
    out = [row[:] for row in grid]
    out[target[0]][target[1]] = 0

    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0 and (r, c) not in markers:
                nr, nc = r + dr, c + dc
                if 0 <= nr < h and 0 <= nc < w:
                    out[nr][nc] = grid[r][c]
    return out
